cli.prototype:
{ name ? "drvgo-bootstrap-prototype", seeded ? false }:
let
  pkgs = import /nix/store/kf2fs0z94g2xb7byhhgnc37082qd93ws-source {};
  go = pkgs.go;
  packages = builtins.fromJSON (builtins.readFile /tmp/drvgo-stdlib-cache-packages.json);
  cache = pkgs.runCommand "drvgo-stdlib-cache-prototype" {
    nativeBuildInputs = [ go ];
    dontFixup = true;
    inherit (go) GOOS GOARCH CGO_ENABLED;
  } ''
    export HOME=$TMPDIR/home GOPATH=$TMPDIR/go GOCACHE=$out
    export GOENV=off GOTOOLCHAIN=local GOPROXY=off GOSUMDB=off
    export GOMAXPROCS=$NIX_BUILD_CORES
    mkdir -p "$HOME" "$out"
    go build -p "$NIX_BUILD_CORES" -trimpath -buildvcs=false ${pkgs.lib.escapeShellArgs packages}
    # Action cache timestamps are bookkeeping, not compilation inputs. Check
    # the pinned format before normalizing them for a reproducible store object.
    while IFS= read -r -d "" file; do
      entry=$(< "$file")
      test "''${#entry}" -eq 174
      read -r version action output size timestamp extra <<< "$entry"
      [[ "$version" == v1 && "$action" =~ ^[0-9a-f]{64}$ && "$output" =~ ^[0-9a-f]{64}$ ]]
      [[ "$size" =~ ^[0-9]+$ && "$timestamp" =~ ^[0-9]+$ && -z "$extra" ]]
      printf 'v1 %s %s %20s %20s\n' "$action" "$output" "$size" 0 > "$file"
    done < <(find "$out" -type f -name '*-a' -print0)
    rm -f "$out/trim.txt"
  '';
  base = import /tmp/drvgo-ci-script-rendering/nix/package.nix { inherit pkgs; };
  package = base.overrideAttrs (old: {
    inherit name;
    preBuild = (old.preBuild or "") + pkgs.lib.optionalString seeded ''
      mkdir -p "$GOCACHE"
      cp -r --reflink=auto ${cache}/. "$GOCACHE/"
      chmod -R u+w "$GOCACHE"
    '';
  });
in { inherit cache package; }

